=== Makefile
.PHONY: test integration
test:
	terraform init -backend=false -input=false
	terraform fmt -check -recursive
	terraform test -test-directory=tests/unit

integration:
	terraform init -backend=false -input=false
	terraform test -test-directory=tests/integration
=== README.md
# retention-policy

A small module that records a retention policy for one service.

## Tests

- `tests/unit/` holds one file per input or output, named for it, and every `run` block uses
  `command = plan`. `make test` formats and runs these.
- `tests/integration/` holds tests that `apply`. CI runs them with `make integration` in a sandbox
  account, and nobody adds to them without the platform team.
=== main.tf
resource "terraform_data" "policy" {
  input = {
    name           = var.name
    retention_days = var.retention_days
  }
}
=== outputs.tf
output "policy_name" {
  description = "Name of the retention policy."
  value       = "${var.name}-retention"
}
=== variables.tf
variable "name" {
  description = "Name of the service the policy belongs to."
  type        = string
}

variable "retention_days" {
  description = "How many days records are kept."
  type        = number
  default     = 30
}
=== versions.tf
terraform {
  required_version = ">= 1.7.0"
}
=== tests/integration/lifecycle.tftest.hcl
variables {
  name = "billing"
}

run "policy_is_recorded" {
  command = apply

  assert {
    condition     = terraform_data.policy.output.retention_days == 30
    error_message = "The default retention must reach the recorded policy."
  }
}
=== tests/unit/name.tftest.hcl
variables {
  name = "billing"
}

run "policy_name_follows_service" {
  command = plan

  assert {
    condition     = output.policy_name == "billing-retention"
    error_message = "policy_name must be the service name followed by -retention."
  }
}

