input.command:
cd /repo/evals/terraform-testing/results/raw/2026-11-05/tt-01-native-suite/with-skill/run-3/workspace
python3 - <<'E'
p='variables.tf'
s=open(p).read()
s=s.replace("  default     = 30\n","  default     = 30\n\n  validation {\n    condition     = var.retention_days >= 1 && var.retention_days <= 365\n    error_message = \"retention_days must be between 1 and 365 inclusive.\"\n  }\n")
open(p,'w').write(s)
E
cat > tests/unit/retention_days.tftest.hcl <<'E'
variables {
  name = "billing"
}

run "retention_days_accepts_lower_bound" {
  command = plan

  variables {
    retention_days = 1
  }

  assert {
    condition     = terraform_data.policy.input.retention_days == 1
    error_message = "retention_days of 1 must be accepted."
  }
}

run "retention_days_accepts_upper_bound" {
  command = plan

  variables {
    retention_days = 365
  }

  assert {
    condition     = terraform_data.policy.input.retention_days == 365
    error_message = "retention_days of 365 must be accepted."
  }
}

run "retention_days_rejects_zero" {
  command = plan

  variables {
    retention_days = 0
  }

  expect_failures = [var.retention_days]
}

run "retention_days_rejects_above_upper_bound" {
  command = plan

  variables {
    retention_days = 366
  }

  expect_failures = [var.retention_days]
}

run "retention_days_rejects_negative" {
  command = plan

  variables {
    retention_days = -5
  }

  expect_failures = [var.retention_days]
}
E
terraform fmt -check -recursive; timeout 300 make test 2>&1 | tail -20
echo ---REVERT; git stash push variables.tf -q; timeout 300 terraform test -test-directory=tests/unit 2>&1 | tail -15; git stash pop -q; git status --short

